use app::compare;
use std::cmp::Ordering::{Equal, Greater, Less};

#[test]
fn spec_example_chain() {
    let chain = [
        "1.0.0-alpha", "1.0.0-alpha.1", "1.0.0-alpha.beta", "1.0.0-beta", "1.0.0-beta.2",
        "1.0.0-beta.11", "1.0.0-rc.1", "1.0.0",
    ];
    for i in 0..chain.len() {
        for j in 0..chain.len() {
            assert_eq!(compare(chain[i], chain[j]), Some(i.cmp(&j)), "{} vs {}", chain[i], chain[j]);
        }
    }
}

#[test]
fn numeric_fields_compare_as_numbers() {
    assert_eq!(compare("2.0.0", "11.0.0"), Some(Less));
    assert_eq!(compare("1.10.0", "1.9.9"), Some(Greater));
    assert_eq!(compare("1.0.0-alpha.10", "1.0.0-alpha.9"), Some(Greater));
    assert_eq!(compare("1.0.0-alpha.1", "1.0.0-alpha.a"), Some(Less));
    assert_eq!(compare("1.0.0-a.b.c", "1.0.0-a.b"), Some(Greater));
}

#[test]
fn numbers_past_u64_still_compare() {
    assert_eq!(compare("18446744073709551616.0.0", "18446744073709551615.0.0"), Some(Greater));
    assert_eq!(compare("1.0.0-99999999999999999999999", "1.0.0-100000000000000000000000"), Some(Less));
}

#[test]
fn build_metadata_is_ignored() {
    assert_eq!(compare("1.0.0+build.1", "1.0.0+build.2"), Some(Equal));
    assert_eq!(compare("1.0.0-rc.1+x", "1.0.0"), Some(Less));
}

#[test]
fn invalid_versions_are_none() {
    for bad in [
        "", "1", "1.0", "1.0.0.0", "01.0.0", "1.00.0", "1.0.0-", "1.0.0-01", "1.0.0-a..b", "v1.0.0",
        "1.0.0+", "1.0.0-a$", " 1.0.0", "1.0.0-alpha_beta", "-1.0.0", "1.0.0+a..b",
    ] {
        assert_eq!(compare(bad, "1.0.0"), None, "{bad:?}");
        assert_eq!(compare("1.0.0", bad), None, "{bad:?}");
    }
    assert_eq!(compare("1.0.0-0a", "1.0.0-0b"), Some(Less), "0a is alphanumeric, valid");
    assert_eq!(compare("1.0.0-x-y", "1.0.0-x"), Some(Greater), "hyphen is allowed");
    assert_eq!(compare("0.0.0", "0.0.0"), Some(Equal));
}

