//! Backoff helper for the sync client.

/// The wait in whole seconds that an HTTP `Retry-After` field value asks for,
/// received when the clock reads `now_unix` seconds since the Unix epoch.
pub fn retry_after(value: &str, _now_unix: u64) -> Option<u64> {
    value.parse().ok()
}

