use app::retry_after;

/// Sun, 06 Nov 1994 08:49:37 GMT (RFC 9110 section 5.6.7 example).
const EXAMPLE: u64 = 784_111_777;

#[test]
fn delta_seconds() {
    assert_eq!(retry_after("120", 0), Some(120));
    assert_eq!(retry_after("0", 5), Some(0));
    assert_eq!(retry_after(" 120\t", 0), Some(120), "optional whitespace around the value");
    for bad in ["", "-1", "+5", "1.5", "1e3", "12 0", "0x10", "  "] {
        assert_eq!(retry_after(bad, 0), None, "{bad:?}");
    }
    assert_eq!(retry_after("99999999999999999999999", 0), None, "past u64 is refused, not wrapped");
}

#[test]
fn imf_fixdate() {
    assert_eq!(retry_after("Sun, 06 Nov 1994 08:49:37 GMT", EXAMPLE - 30), Some(30));
    assert_eq!(retry_after("Sun, 06 Nov 1994 08:49:37 GMT", EXAMPLE + 30), Some(0), "a past date is no wait");
    assert_eq!(retry_after("Wed, 21 Oct 2015 07:28:00 GMT", 1_445_412_480 - 1), Some(1));
    assert_eq!(retry_after("Thu, 29 Feb 2024 23:59:59 GMT", 1_709_251_199 - 10), Some(10), "leap day");
    assert_eq!(retry_after("Fri, 01 Jan 2100 00:00:00 GMT", 4_102_444_800 - 1), Some(1), "2100 is not a leap year");
}

#[test]
fn obsolete_formats_must_be_accepted() {
    assert_eq!(retry_after("Sunday, 06-Nov-94 08:49:37 GMT", EXAMPLE - 7), Some(7), "RFC 850");
    assert_eq!(retry_after("Sun Nov  6 08:49:37 1994", EXAMPLE - 9), Some(9), "asctime");
}

#[test]
fn malformed_dates_are_none() {
    for bad in [
        "Sun, 06 Nov 1994 08:49:37 UTC",
        "Sun, 6 Nov 1994 08:49:37 GMT",
        "Sun, 06 Foo 1994 08:49:37 GMT",
        "Sun, 31 Feb 1994 08:49:37 GMT",
        "Sun, 06 Nov 1994 24:00:00 GMT",
        "Sun, 06 Nov 1994 08:60:00 GMT",
        "06 Nov 1994 08:49:37 GMT",
        "tomorrow",
    ] {
        assert_eq!(retry_after(bad, 0), None, "{bad:?}");
    }
}

