use app::write_record;

/// Why the strict reader refused a record.
#[derive(Debug, PartialEq)]
enum Bad {
    /// The record does not end in CRLF.
    NoCrlf,
    /// Text follows a closing quote.
    AfterQuote,
    /// A quote, CR or LF in an unquoted field.
    Bare(char),
    /// A quoted field never closes.
    Unclosed,
}

/// A strict RFC 4180 reader of one record, used to round-trip what the writer made.
fn read(record: &str) -> Result<Vec<String>, Bad> {
    let body = record.strip_suffix("\r\n").ok_or(Bad::NoCrlf)?;
    let mut fields = Vec::new();
    let mut field = String::new();
    let mut chars = body.chars().peekable();
    let mut quoted = false;
    let mut at_start = true;
    while let Some(c) = chars.next() {
        if at_start && c == '"' {
            quoted = true;
            at_start = false;
            continue;
        }
        at_start = false;
        if quoted {
            if c == '"' {
                if chars.peek() == Some(&'"') {
                    chars.next();
                    field.push('"');
                } else {
                    quoted = false;
                    let next = chars.peek().copied();
                    if next.is_some() && next != Some(',') {
                        return Err(Bad::AfterQuote);
                    }
                }
            } else {
                field.push(c);
            }
        } else if c == ',' {
            fields.push(std::mem::take(&mut field));
            at_start = true;
        } else if c == '"' || c == '\r' || c == '\n' {
            return Err(Bad::Bare(c));
        } else {
            field.push(c);
        }
    }
    if quoted {
        return Err(Bad::Unclosed);
    }
    fields.push(field);
    Ok(fields)
}

#[test]
fn plain_fields() {
    assert_eq!(write_record(&["a", "b", "c"]), "a,b,c\r\n");
    assert_eq!(write_record(&["a b", " x "]), "a b, x \r\n", "spaces are data and need no quotes");
    assert_eq!(write_record(&["", ""]), ",\r\n");
    assert_eq!(write_record(&["é", "日本"]), "é,日本\r\n");
}

#[test]
fn quoting() {
    assert_eq!(write_record(&["a,b"]), "\"a,b\"\r\n");
    assert_eq!(write_record(&["say \"hi\""]), "\"say \"\"hi\"\"\"\r\n");
    assert_eq!(write_record(&["line1\nline2"]), "\"line1\nline2\"\r\n");
    assert_eq!(write_record(&["cr\r"]), "\"cr\r\"\r\n");
    assert_eq!(write_record(&["\""]), "\"\"\"\"\r\n");
}

#[test]
fn one_empty_field_is_not_a_blank_line() {
    assert_eq!(write_record(&[""]), "\"\"\r\n");
    assert_eq!(read(&write_record(&[""])), Ok(vec![String::new()]));
}

#[test]
fn round_trip_every_mix() {
    let pieces = ["", "a", ",", "\"", "\r", "\n", " ", "é", "x,y", "\"\"", "a\r\nb"];
    for a in pieces {
        for b in pieces {
            for c in pieces {
                let fields = [a, b, c];
                let line = write_record(&fields);
                assert_eq!(read(&line), Ok(fields.map(String::from).to_vec()), "{fields:?} -> {line:?}");
            }
        }
    }
    for a in pieces {
        assert_eq!(read(&write_record(&[a])), Ok(vec![a.to_string()]), "{a:?}");
    }
}

