//! Preview text for notification banners.

/// `text` cut to fit `max_bytes`, with an ellipsis when it was cut.
pub fn clip(text: &str, max_bytes: usize) -> String {
    if text.len() <= max_bytes {
        return text.to_string();
    }
    format!("{}...", &text[..max_bytes.saturating_sub(3)])
}

