use app::clip;

/// What `clip` must return, by the rule in the goal.
fn reference(text: &str, max: usize) -> String {
    if text.len() <= max {
        return text.to_string();
    }
    let room = if max >= 3 { max - 3 } else { max };
    let mut end = 0;
    for (index, ch) in text.char_indices() {
        if index + ch.len_utf8() > room {
            break;
        }
        end = index + ch.len_utf8();
    }
    let mut out = text[..end].to_string();
    if max >= 3 {
        out.push('\u{2026}');
    }
    out
}

#[test]
fn short_text_is_unchanged() {
    assert_eq!(clip("hello", 5), "hello");
    assert_eq!(clip("", 0), "");
    assert_eq!(clip("日本", 6), "日本");
}

#[test]
fn ascii_is_cut_with_one_ellipsis_char() {
    assert_eq!(clip("hello world", 8), "hello\u{2026}");
    assert_eq!(clip("hello world", 8).len(), 8);
    assert_eq!(clip("hello", 4), "h\u{2026}");
    assert_eq!(clip("hello", 3), "\u{2026}");
}

#[test]
fn tiny_budgets_get_no_ellipsis() {
    assert_eq!(clip("hello", 2), "he");
    assert_eq!(clip("hello", 1), "h");
    assert_eq!(clip("hello", 0), "");
    assert_eq!(clip("é", 1), "", "never half a character");
}

#[test]
fn multibyte_text_never_splits_a_character() {
    assert_eq!(clip("日本語のテキスト", 10), "日本\u{2026}");
    assert_eq!(clip("😀😀😀", 8), "😀\u{2026}", "8 minus 3 leaves 5: one 4-byte emoji fits");
    assert_eq!(clip("😀😀😀", 6), "\u{2026}", "6 minus 3 leaves 3: no emoji fits");
    assert_eq!(clip("aé😀b", 6), "aé\u{2026}");
}

#[test]
fn every_text_and_budget_matches_the_rule() {
    let texts = ["", "a", "abc", "héllo wörld", "日本語", "😀a😀b😀", "a\u{301}bc", "\u{2026}\u{2026}"];
    for text in texts {
        for max in 0..=text.len() + 2 {
            let got = clip(text, max);
            assert_eq!(got, reference(text, max), "{text:?} at {max}");
            assert!(got.len() <= max || text.len() <= max, "{text:?} at {max} is {} bytes", got.len());
        }
    }
}

