//! Upload storage: where a user-supplied name lands on disk.

use std::path::{Path, PathBuf};

/// Why an upload name was refused.
#[derive(Debug, PartialEq, Eq)]
pub enum PathError {
    /// The name is empty.
    Empty,
    /// The name is absolute.
    Absolute,
    /// The name climbs out of the root.
    Escapes,
    /// The name holds a NUL byte.
    Nul,
}

/// The file under `root` that the upload name `name` refers to.
pub fn resolve(root: &Path, name: &str) -> Result<PathBuf, PathError> {
    if name.is_empty() {
        return Err(PathError::Empty);
    }
    if name.starts_with('/') {
        return Err(PathError::Absolute);
    }
    Ok(root.join(name))
}

