use app::{resolve, PathError};
use std::path::{Path, PathBuf};

fn root() -> &'static Path {
    Path::new("/srv/uploads")
}

fn ok(name: &str) -> Result<PathBuf, PathError> {
    resolve(root(), name)
}

#[test]
fn plain_names_join_under_the_root() {
    assert_eq!(ok("a.txt"), Ok(PathBuf::from("/srv/uploads/a.txt")));
    assert_eq!(ok("docs/2024/a.txt"), Ok(PathBuf::from("/srv/uploads/docs/2024/a.txt")));
    assert_eq!(ok("docs/"), Ok(PathBuf::from("/srv/uploads/docs")));
    assert_eq!(ok("a//b"), Ok(PathBuf::from("/srv/uploads/a/b")));
    assert_eq!(ok("./a/./b"), Ok(PathBuf::from("/srv/uploads/a/b")));
    assert_eq!(ok("a/../b"), Ok(PathBuf::from("/srv/uploads/b")), "dot-dot that stays inside is resolved");
    assert_eq!(ok("."), Ok(PathBuf::from("/srv/uploads")));
    assert_eq!(ok("..."), Ok(PathBuf::from("/srv/uploads/...")), "three dots is a name");
    assert_eq!(ok("a..b"), Ok(PathBuf::from("/srv/uploads/a..b")));
}

#[test]
fn escapes_are_refused_even_when_they_come_back() {
    for name in ["..", "../a", "a/../../b", "a/b/../../..", "../uploads/a", "a/../../uploads/a"] {
        assert_eq!(ok(name), Err(PathError::Escapes), "{name:?}");
    }
}

#[test]
fn windows_separators_count_too() {
    let back = '\\';
    let colon = ':';
    assert_eq!(ok(&format!("a{back}b.txt")), Ok(PathBuf::from("/srv/uploads/a/b.txt")));
    assert_eq!(ok(&format!("..{back}a")), Err(PathError::Escapes));
    assert_eq!(ok(&format!("a{back}..{back}..{back}b")), Err(PathError::Escapes));
    assert_eq!(ok(&format!("{back}a")), Err(PathError::Absolute));
    assert_eq!(ok(&format!("C{colon}{back}a")), Err(PathError::Absolute), "a drive letter is absolute");
    assert_eq!(ok(&format!("c{colon}a")), Err(PathError::Absolute));
}

#[test]
fn other_refusals() {
    assert_eq!(ok(""), Err(PathError::Empty));
    assert_eq!(ok("/etc/passwd"), Err(PathError::Absolute));
    assert_eq!(ok("a\0b"), Err(PathError::Nul));
    assert_eq!(ok("../\0"), Err(PathError::Nul), "NUL is checked before anything else");
}

