//! Splitting a shared bill between people.

/// Why a split was refused.
#[derive(Debug, PartialEq, Eq)]
pub enum SplitError {
    /// Nobody to split between.
    NoShares,
    /// More shares than the app allows.
    TooManyShares,
}

/// The most people one bill may be split between.
pub const MAX_SHARES: u32 = 10_000;

/// `total_cents` split into `shares` parts.
pub fn split(total_cents: i64, shares: u32) -> Result<Vec<i64>, SplitError> {
    if shares == 0 {
        return Err(SplitError::NoShares);
    }
    if shares > MAX_SHARES {
        return Err(SplitError::TooManyShares);
    }
    let each = total_cents / i64::from(shares);
    Ok(vec![each; shares as usize])
}

files.check/t.rs:
use app::{split, SplitError, MAX_SHARES};

fn holds(total: i64, shares: u32) {
    let parts = match split(total, shares) {
        Ok(parts) => parts,
        Err(why) => {
            assert!(false, "{total} over {shares} refused: {why:?}");
            return;
        }
    };
    assert_eq!(parts.len(), shares as usize, "{total}/{shares}: one part per share");
    let sum: i128 = parts.iter().map(|&p| i128::from(p)).sum();
    assert_eq!(sum, i128::from(total), "{total}/{shares}: no cent lost or made");
    let (mut min, mut max) = (i128::MAX, i128::MIN);
    for &part in &parts {
        min = min.min(i128::from(part));
        max = max.max(i128::from(part));
    }
    assert!(max - min <= 1, "{total}/{shares}: parts differ by at most one cent");
    let mut sorted = parts.clone();
    if total >= 0 {
        sorted.sort_by(|a, b| b.cmp(a));
    } else {
        sorted.sort();
    }
    assert_eq!(parts, sorted, "{total}/{shares}: the parts that carry the extra cent come first");
}

#[test]
fn examples() {
    assert_eq!(split(100, 3), Ok(vec![34, 33, 33]));
    assert_eq!(split(-100, 3), Ok(vec![-34, -33, -33]), "a refund: the extra cent of debt comes first");
    assert_eq!(split(-5, 2), Ok(vec![-3, -2]));
    assert_eq!(split(5, 1), Ok(vec![5]));
    assert_eq!(split(2, 5), Ok(vec![1, 1, 0, 0, 0]));
    assert_eq!(split(0, 4), Ok(vec![0, 0, 0, 0]));
}

#[test]
fn refusals() {
    assert_eq!(split(10, 0), Err(SplitError::NoShares));
    assert_eq!(split(10, MAX_SHARES + 1), Err(SplitError::TooManyShares));
    assert_eq!(split(10, u32::MAX), Err(SplitError::TooManyShares));
}

#[test]
fn extremes_never_overflow() {
    holds(i64::MAX, 1);
    holds(i64::MIN, 1);
    holds(i64::MAX, 7);
    holds(i64::MIN, 7);
    holds(i64::MIN, MAX_SHARES);
    holds(i64::MAX, MAX_SHARES);
}

#[test]
fn every_small_case() {
    for total in -200..=200 {
        for shares in 1..=12 {
            holds(total, shares);
        }
    }
}

