//! The last N events the dashboard shows.

/// A fixed-size history that keeps the newest `capacity` events.
#[derive(Debug, Clone)]
pub struct History<T> {
    slots: Vec<Option<T>>,
    next: usize,
    len: usize,
}

impl<T: Clone> History<T> {
    /// An empty history that keeps `capacity` events; a capacity of 0 keeps none.
    pub fn new(capacity: usize) -> Self {
        Self { slots: vec![None; capacity], next: 0, len: 0 }
    }

    /// Records `event`, dropping the oldest one when full.
    pub fn push(&mut self, event: T) {
        if self.slots.is_empty() {
            return;
        }
        self.slots[self.next] = Some(event);
        self.next = (self.next + 1) % (self.slots.len() - 1).max(1);
        if self.len < self.slots.len() {
            self.len += 1;
        }
    }

    /// The newest event.
    pub fn latest(&self) -> Option<&T> {
        if self.len == 0 {
            return None;
        }
        self.slots.get(self.next.saturating_sub(1))?.as_ref()
    }

    /// The events, oldest first.
    pub fn to_vec(&self) -> Vec<T> {
        self.slots.iter().take(self.len).filter_map(|slot| slot.clone()).collect()
    }

    /// How many events are kept.
    pub fn len(&self) -> usize {
        self.len
    }

    /// Whether no event is kept.
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }
}

