use app::History;
use std::collections::VecDeque;

/// The reference: a deque that drops from the front.
fn model(capacity: usize, events: &[u32]) -> VecDeque<u32> {
    let mut kept = VecDeque::new();
    if capacity == 0 {
        return kept;
    }
    for &event in events {
        if kept.len() == capacity {
            kept.pop_front();
        }
        kept.push_back(event);
    }
    kept
}

#[test]
fn every_capacity_and_length_matches_the_reference() {
    for capacity in 0..=6 {
        for count in 0..=20u32 {
            let events: Vec<u32> = (0..count).collect();
            let mut history = History::new(capacity);
            for &event in &events {
                history.push(event);
                let want = model(capacity, &events[..=event as usize]);
                assert_eq!(history.to_vec(), Vec::from(want.clone()), "cap {capacity} after {event}");
                assert_eq!(history.latest(), want.back(), "cap {capacity} latest after {event}");
                assert_eq!(history.len(), want.len(), "cap {capacity} len after {event}");
                assert_eq!(history.is_empty(), want.is_empty());
            }
        }
    }
}

#[test]
fn an_empty_history() {
    let history: History<u32> = History::new(3);
    assert_eq!(history.latest(), None);
    assert!(history.to_vec().is_empty());
    let mut none: History<u32> = History::new(0);
    none.push(1);
    assert_eq!(none.latest(), None);
    assert_eq!(none.len(), 0);
}

#[test]
fn strings_clone_through() {
    let mut history = History::new(2);
    for word in ["a", "b", "c"] {
        history.push(word.to_string());
    }
    assert_eq!(history.to_vec(), ["b", "c"]);
    assert_eq!(history.latest().map(String::as_str), Some("c"));
}

