//! The HTTP handlers, as plain functions.

use crate::users::{fetch_user, User};

/// `GET /users/{id}`: the user's name, or 404.
pub fn get_user_name(id: u64) -> Result<String, u16> {
    match fetch_user(id) {
        Some(user) => Ok(user.name().to_string()),
        None => Err(404),
    }
}

/// `GET /users/{id}/exists`.
pub fn user_exists(id: u64) -> bool {
    fetch_user(id).is_some()
}

/// `GET /users/{a}/same-as/{b}`: whether both ids name one known user.
pub fn same_user(a: u64, b: u64) -> bool {
    let left: Option<User> = fetch_user(a);
    let right: Option<User> = crate::users::fetch_user(b);
    matches!((left, right), (Some(x), Some(y)) if x == y)
}

