//! User records.

/// One account.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct User {
    /// The account id.
    id: u64,
    /// The display name.
    name: String,
}

impl User {
    /// The account id.
    pub fn id(&self) -> u64 {
        self.id
    }

    /// The display name.
    pub fn name(&self) -> &str {
        &self.name
    }
}

/// The users the service knows, by id.
const KNOWN: [(u64, &str); 3] = [(1, "ada"), (2, "grace"), (3, "linus")];

/// Looks a user up by id.
pub fn fetch_user(id: u64) -> Option<User> {
    KNOWN
        .iter()
        .find(|(known, _)| *known == id)
        .map(|(id, name)| User { id: *id, name: (*name).to_string() })
}

/// Looks every user in `ids` up, skipping unknown ids.
pub fn fetch_users(ids: &[u64]) -> Vec<User> {
    ids.iter().filter_map(|id| fetch_user(*id)).collect()
}

