//! Where the server listens.

/// Where a setting came from.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Source {
    /// The `APP_PORT` environment variable.
    Env,
    /// The `port` line of the config file.
    File,
}

/// Why the port setting was refused.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ConfigError {
    /// The value from `source` is not a port from 1 to 65535.
    BadPort {
        /// Where the bad value came from.
        source: Source,
    },
}

/// The port used when neither the environment nor the file sets one.
pub const DEFAULT_PORT: u16 = 8080;

/// The port to listen on, from the `APP_PORT` value and the file's `port` value.
pub fn port(env: Option<&str>, file: Option<&str>) -> Result<u16, ConfigError> {
    if let Some(text) = file {
        if let Ok(port) = text.parse() {
            return Ok(port);
        }
    }
    if let Some(text) = env {
        if let Ok(port) = text.parse() {
            return Ok(port);
        }
    }
    Ok(DEFAULT_PORT)
}

