use app::config::{port, ConfigError, Source, DEFAULT_PORT};

const DOC: &str = include_str!("../CONFIG.md");

fn bad(source: Source) -> Result<u16, ConfigError> {
    Err(ConfigError::BadPort { source })
}

#[test]
fn precedence() {
    assert_eq!(port(None, None), Ok(DEFAULT_PORT));
    assert_eq!(port(Some("9000"), None), Ok(9000));
    assert_eq!(port(None, Some("7000")), Ok(7000));
    assert_eq!(port(Some("9000"), Some("7000")), Ok(9000), "the environment beats the file");
}

#[test]
fn empty_means_unset() {
    assert_eq!(port(Some(""), Some("7000")), Ok(7000), "APP_PORT= is unset, so the file decides");
    assert_eq!(port(Some("   "), None), Ok(DEFAULT_PORT), "blank is empty");
    assert_eq!(port(None, Some("")), Ok(DEFAULT_PORT));
    assert_eq!(port(Some(""), Some("")), Ok(DEFAULT_PORT));
}

#[test]
fn whitespace_is_trimmed() {
    assert_eq!(port(Some(" 9000 "), None), Ok(9000));
    assert_eq!(port(None, Some("\t7000\n")), Ok(7000));
}

#[test]
fn a_bad_value_fails_closed_and_names_its_source() {
    for value in ["0", "65536", "-1", "+80", "80a", "8 0", "0x50", "99999999999"] {
        assert_eq!(port(Some(value), Some("7000")), bad(Source::Env), "env {value:?}");
        assert_eq!(port(None, Some(value)), bad(Source::File), "file {value:?}");
    }
    assert_eq!(port(Some("9000"), Some("nope")), Ok(9000), "a bad file value under a good env value is never read");
    assert_eq!(port(Some("1"), None), Ok(1));
    assert_eq!(port(Some("65535"), None), Ok(65535));
}

#[test]
fn the_doc_says_the_rule() {
    assert!(DOC.contains("APP_PORT"), "names the variable");
    assert!(DOC.contains("65535"), "states the range");
    assert!(!DOC.contains("uses port 8080"), "no longer claims a silent fallback");
    let lower = DOC.to_lowercase();
    assert!(lower.contains("empty"), "says an empty value is unset");
    assert!(lower.contains("refuse") || lower.contains("does not start") || lower.contains("will not start"),
        "says a bad value stops the server");
}

