use app::redact;

#[test]
fn key_value_secrets() {
    assert_eq!(redact("login user=ada password=hunter2 ok"), "login user=ada password=*** ok");
    assert_eq!(redact("GET /cb?code=1&token=abc.def&x=2"), "GET /cb?code=1&token=***&x=2");
    assert_eq!(redact("api_key=k1;secret=s2,next"), "api_key=***;secret=***,next");
    assert_eq!(redact("PASSWORD=x Token=y"), "PASSWORD=*** Token=***", "keys match in any case");
    assert_eq!(redact("password="), "password=***", "an empty value is still hidden");
}

#[test]
fn quoted_values_are_hidden_whole() {
    assert_eq!(redact("password=\"a b c\" next"), "password=*** next");
    assert_eq!(redact("token='x y'"), "token=***");
}

#[test]
fn bearer_tokens() {
    assert_eq!(redact("Authorization: Bearer eyJ.abc.def"), "Authorization: Bearer ***");
    assert_eq!(redact("authorization: bearer abc rest"), "authorization: bearer *** rest");
}

#[test]
fn look_alikes_are_left_alone() {
    assert_eq!(redact("passwordless=true"), "passwordless=true", "a different key");
    assert_eq!(redact("my_password_hint=blue"), "my_password_hint=blue");
    assert_eq!(redact("tokens=5 secretary=bob"), "tokens=5 secretary=bob");
    assert_eq!(redact("no secrets here"), "no secrets here");
    assert_eq!(redact("résumé password=é1 fin"), "résumé password=*** fin", "UTF-8 around a secret");
}

#[test]
fn the_redaction_is_stable() {
    for line in ["password=a token=b", "Authorization: Bearer z", "x"] {
        let once = redact(line);
        assert_eq!(redact(&once), once, "redacting twice changes nothing: {line:?}");
        assert!(!once.contains("hunter2"));
    }
}
